begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('11111111-1111-4111-8111-111111111111','skips@example.invalid',now());
insert into public.profiles(id,username) values('11111111-1111-4111-8111-111111111111','SkipTester');
create temp table results(name text primary key,result jsonb);grant all on results to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
insert into results values('skipped',public.skip_online_scramble('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'));
select is((select (result->>'dnf')::boolean from results where name='skipped'),true,'An inspection skip is a leaderboard DNF');
select is(public.my_leaderboard_candidates(),'[]'::jsonb,'Skipping alone cannot offer a single');
select public.record_online_attempt(public.begin_attempt('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),jsonb_build_object('format','fto-replay-v1','size',3,'complete',true,'solveMs',n,'events','[]'::jsonb)) from unnest(array[100,110,120,130]) n;
insert into results values('one-dnf',(select e from jsonb_array_elements(public.my_leaderboard_candidates()) e where e->>'metric'='ao5'));
select is((select (result->>'ms')::double precision from results where name='one-dnf'),120::double precision,'One hidden DNF is trimmed and the next four solves still offer an ao5');
set local role postgres;
select is((select count(*)::integer from public.attempts where invalid_reason='skipped'),1,'Hidden skip is represented exactly once');
select is((select (e->>'dnf')::boolean from public.submissions s,jsonb_array_elements(s.evidence_refs) e where s.metric='ao5' and e->>'reason'='skipped'),true,'Average evidence labels the hidden DNF as skipped');
set local role authenticated;
select public.submit_leaderboard((select (result->>'id')::uuid from results where name='one-dnf'));
select public.skip_online_scramble('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');
insert into results values('before-two',(select e from jsonb_array_elements(public.my_leaderboard_candidates()) e where e->>'metric'='ao5'));
select public.skip_online_scramble('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');
set local role postgres;
select is((select count(*)::integer from public.submissions where metric='ao5' and status='draft'),0,'Two skipped scrambles remove the stale unsubmitted ao5');
select is((select e->>'ineligible_reason' from jsonb_array_elements(public.my_leaderboard_results()->'ineligible') e where e->>'metric'='ao5'),'leaderboard_dnfs','The current invalid average explains the skipped DNFs');
select is((select ms from public.submissions where metric='ao5' and status='pending'),120::double precision,'Skipping does not remove a previously eligible submission');
set local role authenticated;
select public.record_online_attempt(public.begin_attempt('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),jsonb_build_object('format','fto-replay-v1','size',3,'complete',true,'solveMs',n,'events','[]'::jsonb)) from generate_series(100,200,10) n;
select public.skip_online_scramble('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb');
insert into results values('twelve',(select e from jsonb_array_elements(public.my_leaderboard_candidates()) e where e->>'metric'='ao12'));
select is((select (result->>'ms')::double precision from results where name='twelve'),155::double precision,'ao12 trims one hidden DNF and fastest time from an uninterrupted 12-attempt window');
set local role postgres;
select is((select count(*)::integer from public.attempts),12,'Hidden skips obey the bounded last-12 retention policy');
set local role anon;
select throws_ok($$select public.skip_online_scramble('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')$$,'42501',null,'Anonymous clients cannot create skipped leaderboard attempts');
select * from finish();rollback;
